import React, { Component } from 'react';
import ReactDOM from 'react-dom';
import { SelectableTile } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

class MultiSelectDemo extends Component {
  state = {
    // array of booleans for each of the 4 tiles
    selected: [false, false, false, false],
    lastSelectedIndex: null,
  };

  handleClick = index => evt => {
    this.setState(prev => {
      const { selected, lastSelectedIndex } = prev;
      let newSelected = selected.slice();

      if (evt.shiftKey && lastSelectedIndex !== null) {
        // select the range between the last click and this click
        const [start, end] = [lastSelectedIndex, index].sort((a, b) => a - b);
        newSelected = [false, false, false, false];
        for (let i = start; i <= end; i++) {
          newSelected[i] = true;
        }
      } else {
        // normal toggle
        newSelected[index] = !selected[index];
      }

      return {
        selected: newSelected,
        lastSelectedIndex: index,
      };
    });
  };

  render() {
    return (
      <div style={{ display: 'flex', gap: '1rem' }}>
        {[0, 1, 2, 3].map(i => (
          <SelectableTile
            key={i}
            id={`tile-${i}`}
            name="tiles"
            value={`tile-${i}`}
            selected={this.state.selected[i]}
            handleClick={this.handleClick(i)}
          >
            Tile {i + 1}
          </SelectableTile>
        ))}
      </div>
    );
  }
}

ReactDOM.render(<MultiSelectDemo />, document.getElementById('root'));
